{"action":"write_file","path":"intervals.js","content":"'use strict';

function mergeIntervals(intervals) {
  // Validate input is an array
  if (!Array.isArray(intervals)) {
    throw new TypeError();
  }

  // Empty array returns empty array
  if (intervals.length === 0) {
    return [];
  }

  // Validate and normalize each interval
  const normalized = intervals.map((interval) => {
    if (
      !Array.isArray(interval) ||
      interval.length !== 2 ||
      typeof interval[0] !== 'number' ||
      typeof interval[1] !== 'number' ||
      !Number.isFinite(interval[0]) ||
      !Number.isFinite(interval[1]) ||
      interval[0] > interval[1]
    ) {
      throw new RangeError();
    }
    // Create new arrays (don't modify input)
    return [interval[0], interval[1]];
  });

  // Sort by start position
  normalized.sort((a, b) => a[0] - b[0]);

  // Merge overlapping or touching intervals
  const merged = [normalized[0]];

  for (let i = 1; i < normalized.length; i++) {
    const current = normalized[i];
    const last = merged[merged.length - 1];

    // If current overlaps or touches the last interval, merge them
    if (current[0] <= last[1]) {
      last[1] = Math.max(last[1], current[1]);
    } else {
      // No overlap, add as new interval
      merged.push(current);
    }
  }

  return merged;
}

module.exports = { mergeIntervals };
"}
